code_examples.vulnerable:
// 내부망 중요 정보 획득
http://site_example.com/connect?url=http://192.168.0.45/member/list.json
// 외부 접근 차단된 admin 페이지 접근
http://site_example.com/connect?url=http://192.168.0.45/admin
// 도메인 체크를 우회하여 중요 정보 획득
http://site_example.com/connect?url=http://site_example.com:x@192.168.0.45/member/list.json
// 단축 URL을 이용한 Filter 우회
http://site_example.com/connect?url=http://bit.ly/sdjk3kjhkl3
// 도메인을 사설IP로 설정해 중요정보 획득
http://site_example.com/connect?url=http://internal.site.com/member/list.json
// 서버내 파일 열람
http://site_example.com/connect?url=http://attack/fileview.html

protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    // 사용자 입력값(url)을 검증없이 사용하여 안전하지 않다.
    URL url = new URL(req.getParameter("url"));
    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
}

code_examples.safe:
public class Connect {
    // key, value 형식으로 URL의 리스트를 작성한다.
    private Map<String, URL> urlMap;
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        // 사용자에게 urlMap의 key를 입력받아 urlMap에서 URL값을 참조한다.
        URL url = urlMap.get(req.getParameter("url"));
        // urlMap에서 참조한 값으로 Connection을 만들어 접속한다.
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    }
}
